"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type DragEvent, useEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** Where the drop area is: waiting, sending the file, finished, or failed. */
export type FileDropStatus = "idle" | "uploading" | "done" | "error";

/** Props for a one-file drop area. The area holds its own state and reports through the callbacks. */
export type FileDropProps = Omit<
  ComponentPropsWithoutRef<"div">,
  "children" | "onDrop" | "onDragEnter" | "onDragOver" | "onDragLeave"
> & {
  /** Sends the file. Call `onProgress` with a fraction from 0 to 1. Reject to show the error state. */
  onUpload: (file: File, onProgress: (fraction: number) => void) => Promise<void>;
  onUploaded?: (file: File) => void;
  onRemove?: (file: File) => void;
  /** Limits the file picker only. Check a dropped file inside `onUpload`. */
  accept?: string;
  label?: string;
  /** A short line under the label, for example the allowed types and size. */
  hint?: string;
  disabled?: boolean;
};

const LIFT_SPRING: Transition = { type: "spring", stiffness: 500, damping: 45, mass: 1 };
const ENTER: Transition = { duration: 0.2, ease: [0.165, 0.84, 0.44, 1] };
// The bar stands for work done, so it moves at a constant speed between reports.
const PROGRESS: Transition = { duration: 0.2, ease: "linear" };
const INSTANT: Transition = { duration: 0 };

const GLYPHS = {
  upload: "M8 1.5 3.75 5.75l1.06 1.06 2.44-2.44V11h1.5V4.37l2.44 2.44 1.06-1.06L8 1.5ZM2.5 12.5V14h11v-1.5h-11Z",
  uploading: "M4 1.5h5L12.5 5v8A1.5 1.5 0 0 1 11 14.5H5A1.5 1.5 0 0 1 3.5 13V2a.5.5 0 0 1 .5-.5Z",
  done: "M8 1.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13Zm3.03 5.03-3.5 3.5a.75.75 0 0 1-1.06 0l-1.5-1.5 1.06-1.06.97.97 2.97-2.97 1.06 1.06Z",
  error: "M8 1.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13Zm-.75 3.25h1.5v4h-1.5v-4Zm.75 6.75a.9.9 0 1 1 0-1.8.9.9 0 0 1 0 1.8Z",
  remove: "m4.53 3.47 3.47 3.47 3.47-3.47 1.06 1.06L9.06 8l3.47 3.47-1.06 1.06L8 9.06l-3.47 3.47-1.06-1.06L6.94 8 3.47 4.53l1.06-1.06Z",
};

function Glyph({ name }: { name: keyof typeof GLYPHS }) {
  return (
    <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" className="size-4">
      <path d={GLYPHS[name]} />
    </svg>
  );
}

function formatSize(bytes: number) {
  if (bytes < 1024) return `${bytes} B`;
  const units = ["KB", "MB", "GB"];
  let size = bytes / 1024;
  let unit = 0;
  while (size >= 1024 && unit < units.length - 1) {
    size /= 1024;
    unit += 1;
  }
  return `${size >= 10 ? Math.round(size) : size.toFixed(1)} ${units[unit]}`;
}

const ACTION_CLASS =
  "relative shrink-0 cursor-pointer touch-manipulation rounded-full text-sm font-medium text-foreground outline-none before:absolute before:-inset-2 hover:bg-muted focus-visible:ring-2 focus-visible:ring-ring motion-safe:transition motion-safe:duration-150 active:scale-97";

/**
 * A drop area for one file. It lifts when a file is dragged over it, shows
 * the upload as a bar, then settles on the file name and size, or on an error
 * with a retry. A click or the keyboard opens the file picker.
 */
export function FileDrop({
  onUpload,
  onUploaded,
  onRemove,
  accept,
  label = "Drop a file here or choose one",
  hint,
  disabled = false,
  className,
  ...divProps
}: FileDropProps) {
  const [status, setStatus] = useState<FileDropStatus>("idle");
  const [file, setFile] = useState<File | null>(null);
  const [progress, setProgress] = useState(0);
  const [over, setOver] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const actionRef = useRef<HTMLButtonElement>(null);
  // Each upload gets a number, so a removed or replaced upload cannot report late.
  const runRef = useRef(0);
  const dragDepthRef = useRef(0);
  const keepFocusRef = useRef(false);
  const reduceMotion = useReducedMotion();
  const canTakeFile = !disabled && status !== "uploading";
  const percent = Math.round(progress * 100);

  useEffect(() => {
    const runs = runRef;
    return () => {
      runs.current += 1;
    };
  }, []);

  // The button the person used leaves with its state. Hand focus to the next
  // action, but only when they have not moved on to something else.
  useEffect(() => {
    if (!keepFocusRef.current || status === "uploading") return;
    keepFocusRef.current = false;
    const active = document.activeElement;
    if (active === document.body || rootRef.current?.contains(active)) actionRef.current?.focus();
  }, [status]);

  const upload = async (next: File) => {
    runRef.current += 1;
    const run = runRef.current;
    setFile(next);
    setProgress(0);
    setStatus("uploading");
    try {
      await onUpload(next, (fraction) => {
        if (runRef.current === run) setProgress(Math.min(1, Math.max(0, fraction)));
      });
    } catch {
      // The failure shows as the error state, with a retry.
      if (runRef.current === run) setStatus("error");
      return;
    }
    if (runRef.current !== run) return;
    setProgress(1);
    setStatus("done");
    onUploaded?.(next);
  };

  const remove = () => {
    runRef.current += 1;
    keepFocusRef.current = true;
    if (file) onRemove?.(file);
    setFile(null);
    setStatus("idle");
  };

  const endDrag = (event: DragEvent<HTMLDivElement>, dropped?: File) => {
    event.preventDefault();
    dragDepthRef.current = dropped === undefined ? Math.max(0, dragDepthRef.current - 1) : 0;
    if (dragDepthRef.current === 0) setOver(false);
    if (dropped && canTakeFile) void upload(dropped);
  };

  const messages = {
    idle: "",
    uploading: `Uploading ${file?.name}`,
    done: `${file?.name} uploaded`,
    error: `${file?.name} did not upload`,
  } satisfies Record<FileDropStatus, string>;

  return (
    <div
      {...divProps}
      ref={rootRef}
      data-status={status}
      data-over={over || undefined}
      onDragEnter={(event) => {
        event.preventDefault();
        dragDepthRef.current += 1;
        if (canTakeFile) setOver(true);
      }}
      // Without this the browser refuses the drop and opens the file instead.
      onDragOver={(event) => event.preventDefault()}
      onDragLeave={(event) => endDrag(event)}
      onDrop={(event) => endDrag(event, event.dataTransfer.files[0] ?? undefined)}
      className={cn(
        "grid min-h-32 w-full rounded-xl border bg-background motion-safe:transition-colors motion-safe:duration-150",
        status === "idle" ? "border-dashed" : "border-solid",
        over ? "border-primary bg-muted" : "border-border",
        className,
      )}
    >
      <input
        ref={inputRef}
        type="file"
        hidden
        accept={accept}
        disabled={disabled}
        onChange={(event) => {
          const picked = event.target.files?.[0];
          // Cleared so picking the same file again still fires a change.
          event.target.value = "";
          if (picked) void upload(picked);
        }}
      />
      {status === "idle" || !file ? (
        <button
          ref={actionRef}
          type="button"
          disabled={disabled}
          onClick={() => {
            keepFocusRef.current = true;
            inputRef.current?.click();
          }}
          className="flex cursor-pointer touch-manipulation flex-col items-center justify-center gap-2 rounded-xl p-4 text-sm font-medium text-foreground outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:cursor-not-allowed disabled:opacity-50"
        >
          <motion.span
            initial={false}
            animate={{ y: over && !reduceMotion ? -4 : 0 }}
            transition={LIFT_SPRING}
            className="grid size-9 place-items-center rounded-full bg-muted"
          >
            <Glyph name="upload" />
          </motion.span>
          <span>{over ? "Drop to upload" : label}</span>
          {hint ? <span className="text-xs font-normal text-muted-foreground">{hint}</span> : null}
        </button>
      ) : (
        <motion.div
          initial={reduceMotion ? { opacity: 0 } : { opacity: 0, y: 6 }}
          animate={{ opacity: 1, y: 0 }}
          transition={ENTER}
          className="flex flex-col justify-center gap-3 p-4"
        >
          <div className="flex items-center gap-3">
            <span
              className={cn(
                "grid size-9 shrink-0 place-items-center rounded-full bg-muted",
                status === "error" ? "text-destructive" : "text-foreground",
              )}
            >
              <Glyph name={status} />
            </span>
            <div className="min-w-0 flex-1">
              <p className="truncate text-sm font-medium text-foreground">{file.name}</p>
              <p className={cn("text-xs tabular-nums", status === "error" ? "text-destructive" : "text-muted-foreground")}>
                {status === "uploading" ? `Uploading, ${percent}%` : null}
                {status === "done" ? `${formatSize(file.size)}, uploaded` : null}
                {status === "error" ? "Upload failed" : null}
              </p>
            </div>
            {status === "error" ? (
              <button
                ref={actionRef}
                type="button"
                onClick={() => {
                  keepFocusRef.current = true;
                  void upload(file);
                }}
                className={cn(ACTION_CLASS, "border border-border px-3 py-1.5")}
              >
                Try again
              </button>
            ) : null}
            {status === "done" ? (
              <button
                ref={actionRef}
                type="button"
                aria-label={`Remove ${file.name}`}
                onClick={remove}
                className={cn(ACTION_CLASS, "grid size-7 place-items-center")}
              >
                <Glyph name="remove" />
              </button>
            ) : null}
          </div>
          <div
            role={status === "uploading" ? "progressbar" : undefined}
            aria-hidden={status === "uploading" ? undefined : true}
            aria-label={`Uploading ${file.name}`}
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={percent}
            className="h-1.5 overflow-hidden rounded-full bg-muted"
          >
            <motion.div
              initial={{ scaleX: 0 }}
              animate={{ scaleX: progress }}
              transition={reduceMotion ? INSTANT : PROGRESS}
              className={cn("h-full origin-left rounded-full", status === "error" ? "bg-destructive" : "bg-primary")}
            />
          </div>
        </motion.div>
      )}
      <span role="status" className="sr-only">
        {messages[status]}
      </span>
    </div>
  );
}
